import sys
from collections import deque

sys.setrecursionlimit(200000)

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def buildTree(level_order):
    if not level_order:
        return None

    root = Node(level_order[0])
    queue = deque([root])
    i = 1

    while queue and i < len(level_order):
        current = queue.popleft()

        if i < len(level_order) and level_order[i] is not None:
            current.left = Node(level_order[i])
            queue.append(current.left)
        i += 1

        if i < len(level_order) and level_order[i] is notNone:
            current.right = Node(level_order[i])
            queue.append(current.right)
        i += 1

    return root

def supplyVaccine(root):
    if not root:
        return 0

    count = 0

    def dfs(node):
        nonlocal count
        if not node:
            return 1  # Null node is covered

        left_status = dfs(node.left)
        right_status = dfs(node.right)

        # If any child needs coverage (status == -1), place vaccine here
        if left_status == -1 or right_status == -1:
            count += 1
            return 2  # This node has vaccine, covers parent

        # If any child has vaccine (status == 2), this node is covered
        if left_status == 2 or right_status == 2:
            return 1  # This node is covered, doesn't need vaccine

        # Both children are covered but don't have vaccine
        return -1  # This node needs coverage from parent

    dfs(root)
    return count

def main():
    try:
        line = sys.stdin.readline().strip()
        if not line:
            return
        parts = list(map(int, line.split()))
        n = parts[0]
        if n == 0:
            print(0)
            return

        level_order = []
        for x in parts[1:]:
            if x == -1:
                level_order.append(None)
            else:
                level_order.append(x)

        root = buildTree(level_order)
        result = supplyVaccine(root)
        print(result)
    except Exception:
        pass

if __name__ == "__main__":
    main()
